uniform mat4 transform;
uniform mat4 transformMatrix;
uniform mat4 modelview;
uniform mat4 projection;
uniform mat3 normalMatrix;
uniform vec4 viewport;
uniform vec2 resolution;
uniform vec3 scale;
uniform int perspective, lightCount;
uniform sampler2D ppixels;
uniform vec2 authoredOffset = vec2(0.25, 0.5);
uniform float authoredMetric = 0.125;
uniform float gain;
void calculate_next(in vec3 pos, out vec3 nextPos, out float stepMetric) {
    vec2 matrices = transform[0].xy + transformMatrix[0].xy + modelview[0].xy + projection[0].xy;
    nextPos = vec3(0.75 * texture(ppixels, texCoord).xy + authoredOffset * 0.01
        + viewport.xy * 0.000001 + resolution.xy * 0.0000001 + scale.xy * 0.0001 + matrices * 0.00001, 9.0);
    stepMetric = authoredMetric + float(perspective + lightCount) * 0.01 + normalMatrix[0][0] * 0.1 + gain;
}

